validation.probe:
use Illuminate\Support\Facades\Storage;
foreach ([false, true] as $throw) {
    $disk = Storage::build([
        'driver' => 'local',
        'root' => storage_path('failing-'.(int) $throw),
        'throw' => $throw,
    ]);
    $disk->makeDirectory('occupied');
    try {
        $result = $disk->put('occupied', 'data');
        echo $result === false ? 'false:' : 'true:';
    } catch (League\Flysystem\UnableToWriteFile|League\Flysystem\UnableToCreateDirectory $e) {
        echo 'exception';
    }
}
